SELECT content_id
  FROM content
 WHERE external_id = #{externalId}

SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.content_id, tt1.external_id, tt1.title_ko, tt1.title_org, tt1.overview, TO_CHAR(tt1.release_year, 'YYYY-MM-DD') release_year, tt1.runtime_min, tt1.country, tt1.poster_url, tt1.backdrop_url, TO_CHAR(tt1.created_dt, 'YYYY-MM-DD HH24:MI:SS') created_dt, TO_CHAR(tt1.updated_dt, 'YYYY-MM-DD HH24:MI:SS') updated_dt FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM content
ORDER BY created_dt DESC, content_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content
) B
